Caching an expensive computation or database query server-side, directly extending Module 23's Redis usage to a genuinely different purpose:

import { createClient } from 'redis';
const redisClient = createClient({ url: process.env.REDIS_URL });

async function getPopularProducts() {
  const cached = await redisClient.get('popular-products');
  if (cached) {
    return JSON.parse(cached); // serve the cached result directly,
                                  // skipping the expensive aggregation
                                  // query entirely
  }

  const products = await productsCollection
    .aggregate([{ $sort: { salesCount: -1 } }, { $limit: 10 }])
    .toArray(); // the genuinely expensive operation, only run when
                  // the cache is genuinely empty or has expired

  await redisClient.set('popular-products', JSON.stringify(products), { EX: 300 }); // expires
                                                                                        // after 300
                                                                                        // seconds
  return products;
}

HTTP caching headers, letting browsers and intermediate proxies avoid
requesting again at all:

app.get('/api/products/:id', (req, res) => {
  res.set('Cache-Control', 'public, max-age=3600'); // this specific
    // response can be reused for up to 1 hour, with NO request to
    // this server needed at all during that window
  res.json(product);
});

