import { createClient } from 'redis';
const redisClient = createClient({ url: process.env.REDIS_URL });

async function getProduct(productId: string) {
  const cacheKey = `product:${productId}`;
  const cached = await redisClient.get(cacheKey);
  if (cached) return JSON.parse(cached);

  const product = await productsCollection.findOne({ _id: new ObjectId(productId) });
  await redisClient.set(cacheKey, JSON.stringify(product), { EX: 3600 }); // a
    // 1-hour fallback expiration, in case explicit invalidation below
    // is ever somehow missed - defense in depth, Module 7 lesson 6's
    // exact philosophy applied to caching specifically
  return product;
}

async function updateProductPrice(productId: string, newPrice: number) {
  await productsCollection.updateOne(
    { _id: new ObjectId(productId) },
    { $set: { price: newPrice } }
  );

  // EXPLICIT invalidation - the MOMENT the underlying data genuinely
  // changes, immediately remove the now-stale cached entry, rather
  // than waiting for its time-based expiration to eventually catch up
  await redisClient.del(`product:${productId}`);
}

