async function getUserProfile(userId: string) {
  const cacheKey = `user-profile:${userId}`;
  const cached = await redisClient.get(cacheKey);
  if (cached) return JSON.parse(cached);

  const profile = await usersCollection.findOne({ _id: new ObjectId(userId) });
  await redisClient.set(cacheKey, JSON.stringify(profile), { EX: 3600 });
  return profile;
}

async function updateUserProfile(userId: string, updates: Partial<UserProfile>) {
  await usersCollection.updateOne(
    { _id: new ObjectId(userId) },
    { $set: updates }
  );

  await redisClient.del(`user-profile:${userId}`);
}

