A systematic diagnostic sequence for a slow, database-backed endpoint:

// STEP 1 - count actual queries (lesson 3's N+1 diagnostic)
let queryCount = 0;
// ... instrument and run the endpoint, observe queryCount ...
// If queryCount scales with result size: N+1 problem (lesson 3's fix)

// STEP 2 - if query count is genuinely reasonable, check EACH
// individual query's own execution plan (Module 19's diagnostic)
db.products.find({ category: 'electronics', inStock: true }).explain('executionStats');
// If totalDocsExamined far exceeds nReturned: missing index
// (Module 19's exact fix - create the appropriate compound index)

// STEP 3 - if individual queries are already well-indexed and
// efficient, but the SAME expensive result is requested repeatedly
// with data that doesn't change often: caching opportunity (lesson 4)
async function getPopularProducts() {
  const cached = await redisClient.get('popular-products');
  if (cached) return JSON.parse(cached); // skip the (already
                                            // well-indexed) query
                                            // entirely on a cache hit
  // ... otherwise run the well-indexed query and cache the result ...
}

